// === Tab: mySketch ===
let mass = [];
let positionX = [];
let positionY = [];
let velocityX = [];
let velocityY = [];
let colors = [];

function setup() {
	createCanvas(windowWidth, windowHeight);
	noStroke();
	background(0);
}

function draw() {
	fill(0, 10); // Semi-transparent fill to create trails
	rect(0, 0, width, height);

	for (let a = 0; a < mass.length; a++) {
		let ax = 0, ay = 0;

		for (let b = 0; b < mass.length; b++) {
			if (a !== b) {
				let dx = positionX[b] - positionX[a];
				let dy = positionY[b] - positionY[a];
				let d = sqrt(dx * dx + dy * dy);
				if (d < 1) d = 1;

				let force = (d - 200) * mass[b] / d;
				ax += force * dx;
				ay += force * dy;
			}
		}

		velocityX[a] = velocityX[a] * 0.98 + ax * mass[a];
		velocityY[a] = velocityY[a] * 0.98 + ay * mass[a];
	}

	for (let i = 0; i < mass.length; i++) {
		positionX[i] += velocityX[i];
		positionY[i] += velocityY[i];

		fill(colors[i][0], colors[i][1], colors[i][2], 100);
		ellipse(positionX[i], positionY[i], mass[i] * 1200, mass[i] * 1200);
	}
}

function addNewParticle() {
	mass.push(random(0.005, 0.02));
	positionX.push((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))));
	positionY.push((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));
	velocityX.push(random(-1, 1));
	velocityY.push(random(-1, 1));
	colors.push([
		random(200, 255),
		random(200, 255),
		random(200, 255)
	]);
}

function mouseClicked() {
	addNewParticle();
}

function mouseDragged() {
	addNewParticle();
}

